from invoicer.money import total

CURRENCY_SYMBOLS = {"EUR": "\u20ac", "USD": "$", "GBP": "\u00a3"}


def _currency(value):
    if value not in CURRENCY_SYMBOLS:
        raise argparse.ArgumentTypeError(
            f"unsupported currency {value!r}; choose EUR, USD or GBP"
        )
    return value


def main(argv=None):
